import {summarize,SKILLED,validityRollups} from './skill/report.js';import {BANDS,readMatches,exportMatches} from './skill/telemetry.js';
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const table=(heads,rows)=>`<div class="scroll"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const pct=(x,n)=>n?`${(100*x/n).toFixed(1)}% (${x}/${n})`:'no sample';
export function renderReport(report){
 if(report?.kind!=='rift-skill-report'||report.schema!==1||!Array.isArray(report.matches))throw Error('Choose a Skill Lab report or live export (schema 1).');
 for(const m of report.matches)if(!Array.isArray(m.players)||m.players.length!==2||!Array.isArray(m.fighters))throw Error('Invalid match record');
 const rows=report.matches,s=summarize(rows);let html=`<section class="panel"><h2>${esc(report.created||'Live match export')}</h2><p>${rows.length} bouts · ${rows.filter(m=>m.completed).length} completed · ${rows.filter(m=>!m.completed).length} unfinished/training samples</p>${s.summary.map(x=>`<p class="warning">${esc(x)}</p>`).join('')}</section>`;
 for(const [mode,v] of Object.entries(s.modes)){
  const matches=rows.filter(m=>m.mode===mode),bots=Object.keys(v.grid);
  html+=`<section class="panel"><h2>${esc(mode)} <small>n=${v.n} bouts</small></h2><h3>Bot versus bot · strict wins</h3>${table(['Bot',...bots],bots.map(a=>[a,...bots.map(b=>a===b?'—':pct(v.grid[a][b].wins,v.grid[a][b].n))]))}<h3>Skill versus mashing by fighter</h3>${table(['Fighter','Skilled wins / bouts','Draws'],Object.entries(v.fighters).map(([f,r])=>[f,pct(r.wins,r.n),r.draws]))}<h3>Sanity check · wins against random</h3>${table(['Policy','Wins / bouts','95% interval','Trust'],Object.entries(v.sanity).map(([b,r])=>[b,pct(r.wins,r.n),r.interval.map(x=>(100*x).toFixed(1)+'%').join('–'),r.trusted?'passes screen':'UNTRUSTWORTHY']))}</section>`;
  html+=`<section class="panel"><h3>Bot validity · actual contacts and move starts</h3>${table(['Policy','Bouts','Shots received / guarded','Basic / directional specials','Punish attempts'],validityRollups(matches).map(v=>[v.bot,v.playerBouts,v.shotsReceived==null?'not recorded':`${v.shotsReceived} / ${v.shotsGuarded}`,v.basicStrikesStarted==null?'not recorded':`${v.basicStrikesStarted} / ${v.directionalSpecialsStarted}`,v.punishAttemptsStarted??'not recorded']))}</section>`;
  const players=matches.flatMap(m=>m.players.map((p,i)=>({...p,bot:m.bots?.[i]||'human / CPU',fighter:m.fighters[i],seconds:m.seconds})));
  const groups=[['masher',p=>p.bot==='masher'],['skilled policies',p=>SKILLED.includes(p.bot)],['human / CPU',p=>p.bot==='human / CPU']];
  html+=`<section class="panel"><h3>Mash payoff · all damage / attack presses</h3>${table(['Group','Damage / presses','Presses','Player-bouts'],groups.map(([name,filter])=>{const ps=players.filter(filter),press=ps.reduce((s,p)=>s+p.attackPresses,0),d=ps.reduce((s,p)=>s+p.damage,0);return [name,press?(d/press).toFixed(3):'—',press,ps.length];}))}<h3>Guard and whiff outcomes</h3>${table(['Policy','n player-bouts','Whiffs / melee attempts','Punished / whiffs','Blocks','Perfect guards','Breaks','Captures through guard','Chip taken'],[...new Set(players.map(p=>p.bot))].map(b=>{const ps=players.filter(p=>p.bot===b),sum=k=>ps.reduce((n,p)=>n+p[k],0);return [b,ps.length,pct(sum('whiffs'),sum('meleeAttempts')),pct(sum('punishedWhiffs'),sum('whiffs')),sum('blocks'),sum('perfectGuards'),sum('captureBreaks'),sum('capturesThroughGuard'),sum('chipTaken').toFixed(1)];}))}</section>`;
  html+=`<section class="panel"><h3>Distance time and option variety</h3><p>Distance is relative to each fighter’s reach. Bars use unfrozen simulation frames. Variety is damage share from each player-bout’s most frequently started move, averaged; unresolved damage is shown separately.</p>`;
  for(const f of [...new Set(players.map(p=>p.fighter))]){const ps=players.filter(p=>p.fighter===f),frames=ps.reduce((s,p)=>s+Object.values(p.distanceFrames).reduce((a,b)=>a+b,0),0),damaged=ps.filter(p=>p.damage>0);html+=`<h3>${esc(f)} · n=${ps.length} player-bouts</h3>${BANDS.map(b=>{const n=ps.reduce((s,p)=>s+p.distanceFrames[b],0);return `<div>${b} <meter min="0" max="1" value="${frames?n/frames:0}"></meter> ${pct(n,frames)} frames</div>`;}).join('')}<p>Dominant move: ${damaged.length?(100*damaged.reduce((s,p)=>s+p.dominantMoveShare,0)/damaged.length).toFixed(1)+'%':'—'} mean share (n=${damaged.length} damaging player-bouts). Unresolved damage: ${ps.reduce((s,p)=>s+Object.entries(p.damageByMove).filter(([k])=>k==='unknown'||k.includes('unresolved')).reduce((a,[,v])=>a+v,0),0).toFixed(1)} HP (n=${ps.length} player-bouts).</p>`;}
  const causes={};for(const m of matches)causes[m.koCause||'unfinished']=(causes[m.koCause||'unfinished']||0)+1;
  html+=`<h3>Round length and endings</h3><p>${(matches.reduce((s,m)=>s+m.seconds,0)/(matches.length||1)).toFixed(1)} seconds mean (n=${matches.length} bouts, includes hitstop).</p>${table(['End / KO damage source','Bouts'],Object.entries(causes))}</section>`;
 }
 return html+`<details><summary>Method and limits</summary>${(report.notes||['Live exports are observational. No bot win-rate conclusion is available without bot bouts.']).map(n=>`<p>${esc(n)}</p>`).join('')}</details>`;
}
function show(id,r){const el=document.getElementById(id);el.classList.remove('grab-study');el.innerHTML=renderReport(r);el.hidden=false;document.getElementById('error').textContent='';}
for(const id of ['A','B'])document.getElementById('file'+id).onchange=async e=>{try{show(id,JSON.parse(await e.target.files[0].text()));}catch(e){document.getElementById('error').textContent=e.message;}};
document.getElementById('theme').onclick=()=>document.body.classList.toggle('light');
document.getElementById('saved').onclick=()=>{try{show('A',exportMatches(readMatches(localStorage)));}catch(e){document.getElementById('error').textContent=e.message;}};
document.getElementById('latest').onclick=async()=>{try{const r=await fetch('../art/skill-lab/2026-10-28/report.json');if(!r.ok)throw Error('Local report not found. Import report.json instead.');show('A',await r.json());}catch(e){document.getElementById('error').textContent=e.message;}};
if(new URLSearchParams(location.search).has('saved'))document.getElementById('saved').click();

document.getElementById('full').onclick=async()=>{try{const r=await fetch('../art/skill-lab/2026-10-28/full/report.json');if(!r.ok)throw Error('Both-seat report not found. Run --full or import a report.');show('A',await r.json());}catch(e){document.getElementById('error').textContent=e.message;}};
if(new URLSearchParams(location.search).get('report')==='full')document.getElementById('full').click();

// Keep the original report buttons and files available; compare corrected runs alongside them.
async function botStudy(run='full-15'){
 try{
  const base='../art/skill-lab/2026-10-28-skill-bots/';
  const fetchJSON=async path=>{const r=await fetch(path);if(!r.ok)throw Error('Report unavailable: '+path);return r.json();};
  const study=await fetchJSON(base+'study.json');
  const old=run.startsWith('full')?'../art/skill-lab/2026-10-28/full/report.json':'../art/skill-lab/2026-10-28/report.json';
  const [a,b]=await Promise.all([fetchJSON(old),fetchJSON(base+run+'/report.json')]);show('A',a);show('B',b);document.querySelector('#A h2').prepend('Original · ');document.querySelector('#B h2').prepend('Corrected · ');
  let panel=document.getElementById('bot-study');if(!panel){panel=document.createElement('section');panel.id='bot-study';panel.className='panel';document.getElementById('A').parentElement.before(panel);}
  panel.innerHTML=`<h2>Bot fixes · old and new</h2><p>Left: original 15f ${run.startsWith('full')?'mirrored':'quick'} run. Right: corrected ${esc(run)}. Quick alternates seats; full mirrors every pairing. The original three-policy aggregate is kept unchanged; punisher is reported separately.</p><label>Corrected run <select id="study-run">${['quick-6','quick-10','quick-15','full-15'].map(k=>`<option ${k===run?'selected':''}>${k}</option>`).join('')}</select></label>${table(['Run','Mode','Original three vs masher','Punisher vs masher','Capture share in punisher losses'],study.runs.flatMap(r=>Object.entries(r.modes).map(([mode,v])=>{const p=v.vsMasher.punisher,c=v.capture.inPunisherLosses;return [r.name,mode,pct(v.gap.wins,v.gap.n),p?pct(p.wins,p.n):'not run',c.n?`${(100*c.share).toFixed(1)}% (${c.n} bouts)`:'not run'];})))}<p>Capture share uses actual HP damage. These are bot measurements, not a verdict about skilled human play. Old counters not recorded are shown as missing.</p>`;
  document.getElementById('study-run').onchange=e=>botStudy(e.target.value);
 }catch(e){document.getElementById('error').textContent=e.message;}
}
const studyButton=document.createElement('button');studyButton.textContent='Compare corrected bots';studyButton.id='corrected';studyButton.onclick=()=>botStudy();document.getElementById('full').after(studyButton);
if(new URLSearchParams(location.search).get('study')==='skill-bots')botStudy(new URLSearchParams(location.search).get('run')||'full-15');

async function showGrabStudy(){try{
 const r=await fetch('../art/skill-lab/2026-10-28-grab-options/summary.json');if(!r.ok)throw Error('Grab study not yet available.');const study=await r.json();
 const {winText,compareModes}=await import('./skill/grab-report.js');
 document.getElementById('B').hidden=true;const a=document.getElementById('A');a.classList.add('grab-study');a.innerHTML=`<section class="panel"><h2>Grab options · five seeds, mirrored seats</h2><p>${study.runs.reduce((s,r)=>s+r.bouts,0)} bouts. Every option is a preview; no default rules changed.</p>${study.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</section>`;
 for(const delay of [10,15]){const rows=study.runs.filter(r=>r.config.delay===delay);a.innerHTML+=`<section class="panel"><h2>${delay}f reaction delay · modes side by side</h2>${table(['Group / opponent',...rows.map(r=>r.config.mode)],Object.keys(rows[0].outcomes).map(k=>[k,...rows.map(r=>winText(r.outcomes[k]))]))}<h3>Difference from proposed alone</h3>${table(['Group / opponent',...rows.map(r=>r.config.mode)],Object.keys(rows[0].outcomes).map(k=>[k,...rows.map(r=>`${r.comparisons[k].difference.toFixed(1)} pp; ${r.comparisons[k].label}`)]))}<h3>Capture share and breaks</h3>${table(['Mode','Masher','Capture damage share','Opponent breaks / masher breaks'],rows.flatMap(r=>Object.entries(r.captures).map(([k,v])=>[r.config.mode,k,`${(100*v.share).toFixed(1)}% (${v.captureDamage.toFixed(1)}/${v.damage.toFixed(1)} HP)`,`${v.breaksAgainstMasher} / ${v.breaksByMasher}`])))}<h3>Sanity against random</h3>${table(['Mode','Policy','Wins and 95% range','Screen'],rows.flatMap(r=>Object.entries(r.sanity).map(([k,v])=>[r.config.mode,k,winText(v),v.interval[0]>.5?'passes':'UNTRUSTED'])))}<details><summary>Compare any two modes</summary>${table(['Group / opponent','A','B','A minus B','Interpretation'],rows.flatMap((a,i)=>rows.slice(i+1).flatMap(b=>Object.keys(a.outcomes).map(k=>{const c=compareModes(a.outcomes[k],b.outcomes[k]);return [k,a.config.mode,b.config.mode,c.difference.toFixed(1)+' pp',c.label];}))))}</details></section>`;}
 document.getElementById('error').textContent='';
 }catch(e){document.getElementById('error').textContent=e.message;}
}
const grabButton=document.createElement('button');grabButton.id='grab-study';grabButton.textContent='Compare grab options';grabButton.onclick=showGrabStudy;document.getElementById('corrected').after(grabButton);
if(new URLSearchParams(location.search).get('study')==='grab-options')showGrabStudy();
